     1→"use server";
     2→
     3→import { createServerSupabaseClient, createAdminClient } from "@/app/lib/supabase-server";
     4→import { revalidatePath } from "next/cache";
     5→
     6→export type ConversationWithMeta = {
     7→  id: string;
     8→  updated_at: string;
     9→  otherUser: {
    10→    id: string;
    11→    full_name: string;
    12→  };
    13→  lastMessage: {
    14→    body: string;
    15→    created_at: string;
    16→    sender_id: string;
    17→  } | null;
    18→  unreadCount: number;
    19→};
    20→
    21→export type MessageRow = {
    22→  id: string;
    23→  conversation_id: string;
    24→  sender_id: string;
    25→  body: string;
    26→  created_at: string;
    27→  read_at: string | null;
    28→};
    29→
    30→export async function getConversations(userId: string): Promise<ConversationWithMeta[]> {
    31→  const supabase = await createServerSupabaseClient();
    32→  const adminClient = createAdminClient();
    33→
    34→  // Get all conversation IDs the user is in
    35→  const { data: participantRows, error: pErr } = await supabase
    36→    .schema("messaging")
    37→    .from("conversation_participants")
    38→    .select("conversation_id")
    39→    .eq("user_id", userId);
    40→
    41→  if (pErr) console.error("[getConversations] participantRows error:", pErr);
    42→  if (pErr || !participantRows?.length) return [];
    43→
    44→  const conversationIds = participantRows.map((r) => r.conversation_id);
    45→
    46→  // Get conversations
    47→  const { data: convos, error: cErr } = await supabase
    48→    .schema("messaging")
    49→    .from("conversations")
    50→    .select("id, updated_at")
    51→    .in("id", conversationIds)
    52→    .order("updated_at", { ascending: false });
    53→
    54→  if (cErr) console.error("[getConversations] convos error:", cErr);
    55→  if (cErr || !convos?.length) return [];
    56→
    57→  // For each conversation, get the other participant's user_id
    58→  const { data: allParticipants } = await supabase
    59→    .schema("messaging")
    60→    .from("conversation_participants")
    61→    .select("conversation_id, user_id")
    62→    .in("conversation_id", conversationIds);
    63→
    64→  // Get the other user ids (not current user)
    65→  const otherUserIds = [
    66→    ...new Set(
    67→      (allParticipants ?? [])
    68→        .filter((p) => p.user_id !== userId)
    69→        .map((p) => p.user_id)
    70→    ),
    71→  ];
    72→
    73→  // Fetch full_name from admin.users for those ids
    74→  const { data: adminUsers } = await adminClient
    75→    .schema("admin")
    76→    .from("users")
    77→    .select("id, full_name")
    78→    .in("id", otherUserIds);
    79→
    80→  const userMap = new Map((adminUsers ?? []).map((u) => [u.id, u]));
    81→
    82→  // Get latest message + unread count for each conversation
    83→  const result: ConversationWithMeta[] = await Promise.all(
    84→    convos.map(async (convo) => {
    85→      const otherParticipant = (allParticipants ?? []).find(
    86→        (p) => p.conversation_id === convo.id && p.user_id !== userId
    87→      );
    88→      const otherUser = otherParticipant
    89→        ? userMap.get(otherParticipant.user_id)
    90→        : null;
    91→
    92→      const { data: messages } = await supabase
    93→        .schema("messaging")
    94→        .from("messages")
    95→        .select("id, body, created_at, sender_id, read_at")
    96→        .eq("conversation_id", convo.id)
    97→        .order("created_at", { ascending: false })
    98→        .limit(1);
    99→
   100→      const lastMessage = messages?.[0] ?? null;
   101→
   102→      const { count: unreadCount } = await supabase
   103→        .schema("messaging")
   104→        .from("messages")
   105→        .select("id", { count: "exact", head: true })
   106→        .eq("conversation_id", convo.id)
   107→        .neq("sender_id", userId)
   108→        .is("read_at", null);
   109→
   110→      return {
   111→        id: convo.id,
   112→        updated_at: convo.updated_at,
   113→        otherUser: {
   114→          id: otherUser?.id ?? otherParticipant?.user_id ?? "",
   115→          full_name: otherUser?.full_name ?? "Unknown",
   116→        },
   117→        lastMessage: lastMessage
   118→          ? {
   119→              body: lastMessage.body,
   120→              created_at: lastMessage.created_at,
   121→              sender_id: lastMessage.sender_id,
   122→            }
   123→          : null,
   124→        unreadCount: unreadCount ?? 0,
   125→      };
   126→    })
   127→  );
   128→
   129→  return result;
   130→}
   131→
   132→export async function getMessages(conversationId: string): Promise<MessageRow[]> {
   133→  const supabase = await createServerSupabaseClient();
   134→
   135→  const { data, error } = await supabase
   136→    .schema("messaging")
   137→    .from("messages")
   138→    .select("id, conversation_id, sender_id, body, created_at, read_at")
   139→    .eq("conversation_id", conversationId)
   140→    .order("created_at", { ascending: true });
   141→
   142→  if (error) return [];
   143→  return data ?? [];
   144→}
   145→
   146→export async function sendMessage(conversationId: string, body: string): Promise<MessageRow | null> {
   147→  const supabase = await createServerSupabaseClient();
   148→  const { data: { user } } = await supabase.auth.getUser();
   149→  if (!user) return null;
   150→
   151→  const { data, error } = await supabase
   152→    .schema("messaging")
   153→    .from("messages")
   154→    .insert({ conversation_id: conversationId, sender_id: user.id, body })
   155→    .select()
   156→    .single();
   157→
   158→  if (error) return null;
   159→
   160→  // Update conversation updated_at
   161→  await supabase
   162→    .schema("messaging")
   163→    .from("conversations")
   164→    .update({ updated_at: new Date().toISOString() })
   165→    .eq("id", conversationId);
   166→
   167→  revalidatePath("/parent/messages");
   168→  return data;
   169→}
   170→
   171→export async function createConversation(
   172→  currentUserId: string,
   173→  recipientId: string
   174→): Promise<string | null> {
   175→  const supabase = await createServerSupabaseClient();
   176→  const adminClient = createAdminClient();
   177→
   178→  // Check if a 1-on-1 conversation already exists between these two users
   179→  const { data: myConvos } = await supabase
   180→    .schema("messaging")
   181→    .from("conversation_participants")
   182→    .select("conversation_id")
   183→    .eq("user_id", currentUserId);
   184→
   185→  if (myConvos?.length) {
   186→    const myConvoIds = myConvos.map((r) => r.conversation_id);
   187→    const { data: sharedConvos } = await adminClient
   188→      .schema("messaging")
   189→      .from("conversation_participants")
   190→      .select("conversation_id")
   191→      .eq("user_id", recipientId)
   192→      .in("conversation_id", myConvoIds);
   193→
   194→    if (sharedConvos?.length) {
   195→      return sharedConvos[0].conversation_id;
   196→    }
   197→  }
   198→
   199→  // Use admin client for all writes — bypasses RLS for conversation creation
   200→  const { data: newConvo, error: cErr } = await adminClient
   201→    .schema("messaging")
   202→    .from("conversations")
   203→    .insert({})
   204→    .select("id")
   205→    .single();
   206→
   207→  if (cErr || !newConvo) {
   208→    console.error("[createConversation] insert conversation error:", cErr);
   209→    return null;
   210→  }
   211→  console.log("[createConversation] created conversation:", newConvo.id);
   212→
   213→  const { error: p1Err } = await adminClient
   214→    .schema("messaging")
   215→    .from("conversation_participants")
   216→    .insert({ conversation_id: newConvo.id, user_id: currentUserId });
   217→
   218→  if (p1Err) {
   219→    console.error("[createConversation] insert self participant error:", p1Err);
   220→    return null;
   221→  }
   222→  console.log("[createConversation] inserted self participant:", currentUserId);
   223→
   224→  const { error: p2Err } = await adminClient
   225→    .schema("messaging")
   226→    .from("conversation_participants")
   227→    .insert({ conversation_id: newConvo.id, user_id: recipientId });
   228→
   229→  if (p2Err) {
   230→    console.error("[createConversation] insert other participant error:", p2Err);
   231→    return null;
   232→  }
   233→  console.log("[createConversation] inserted other participant:", recipientId);
   234→
   235→  return newConvo.id;
   236→}
   237→
   238→export async function searchUsers(query: string): Promise<{ id: string; full_name: string }[]> {
   239→  if (!query.trim()) return [];
   240→  const adminClient = createAdminClient();
   241→
   242→  const { data, error } = await adminClient
   243→    .schema("admin")
   244→    .from("users")
   245→    .select("id, full_name")
   246→    .ilike("full_name", `%${query}%`)
   247→    .limit(10);
   248→
   249→  if (error) return [];
   250→  return data ?? [];
   251→}
   252→
   253→export async function markMessagesRead(conversationId: string, userId: string): Promise<void> {
   254→  const supabase = await createServerSupabaseClient();
   255→  await supabase
   256→    .schema("messaging")
   257→    .from("messages")
   258→    .update({ read_at: new Date().toISOString() })
   259→    .eq("conversation_id", conversationId)
   260→    .neq("sender_id", userId)
   261→    .is("read_at", null);
   262→}
