     3→import { useState, useRef, useEffect, useCallback } from "react";
     4→import { Search, Send, ChevronLeft, SquarePen, X, Loader2 } from "lucide-react";
     5→import { createClient } from "@/app/lib/supabase-browser";
     6→import {
     7→  getConversations,
     8→  getMessages,
     9→  sendMessage,
    10→  createConversation,
    11→  searchUsers,
    12→  markMessagesRead,
    13→  type ConversationWithMeta,
    14→  type MessageRow,
    15→} from "./actions";
    16→
    17→// Deterministic color from a string (user id)
    18→const AVATAR_COLORS = [
    19→  "bg-[#4a7c59]",
    20→  "bg-[#7c6b4a]",
    21→  "bg-[#5a6b8a]",
    22→  "bg-[#8a5a6b]",
    23→  "bg-[#6b7c4a]",
    24→  "bg-[#4a6b7c]",
    25→];
    26→
    27→function colorForId(id: string): string {
    28→  let hash = 0;
    29→  for (let i = 0; i < id.length; i++) hash = id.charCodeAt(i) + ((hash << 5) - hash);
    30→  return AVATAR_COLORS[Math.abs(hash) % AVATAR_COLORS.length];
    31→}
    32→
    33→function initialsFor(name: string): string {
    34→  return name
    35→    .split(" ")
    36→    .filter(Boolean)
    37→    .slice(0, 2)
    38→    .map((w) => w[0].toUpperCase())
    39→    .join("");
    40→}
    41→
    42→function formatTime(iso: string): string {
    43→  const date = new Date(iso);
    44→  const now = new Date();
    45→  const diffDays = Math.floor((now.getTime() - date.getTime()) / 86400000);
    46→  if (diffDays === 0)
    47→    return date.toLocaleTimeString([], { hour: "numeric", minute: "2-digit" });
    48→  if (diffDays === 1) return "Yesterday";
    49→  if (diffDays < 7)
    50→    return date.toLocaleDateString([], { weekday: "short" });
    51→  return date.toLocaleDateString([], { month: "short", day: "numeric" });
    52→}
    53→
    54→export default function MessagesPage({ userId }: { userId: string }) {
    55→  const [conversations, setConversations] = useState<ConversationWithMeta[]>([]);
    56→  const [activeId, setActiveId] = useState<string | null>(null);
    57→  const [messages, setMessages] = useState<MessageRow[]>([]);
    58→  const [search, setSearch] = useState("");
    59→  const [draft, setDraft] = useState("");
    60→  const [mobileShowChat, setMobileShowChat] = useState(false);
    61→  const [loadingConvos, setLoadingConvos] = useState(true);
    62→  const [loadingMessages, setLoadingMessages] = useState(false);
    63→  const [sending, setSending] = useState(false);
    64→
    65→  // New message modal
    66→  const [showNewModal, setShowNewModal] = useState(false);
    67→  const [recipientSearch, setRecipientSearch] = useState("");
    68→  const [recipientResults, setRecipientResults] = useState<{ id: string; full_name: string }[]>([]);
    69→  const [searchingUsers, setSearchingUsers] = useState(false);
    70→  const [creatingConvo, setCreatingConvo] = useState(false);
    71→
    72→  const messagesEndRef = useRef<HTMLDivElement>(null);
    73→  const searchDebounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    74→
    75→  const active = conversations.find((c) => c.id === activeId) ?? null;
    76→
    77→  // Load conversations on mount
    78→  useEffect(() => {
    79→    getConversations(userId).then((data) => {
    80→      setConversations(data);
    81→      setLoadingConvos(false);
    82→    });
    83→  }, [userId]);
    84→
    85→  // Load messages when active conversation changes
    86→  useEffect(() => {
    87→    if (!activeId) return;
    88→    setLoadingMessages(true);
    89→    getMessages(activeId).then((data) => {
    90→      setMessages(data);
    91→      setLoadingMessages(false);
    92→      markMessagesRead(activeId, userId);
    93→      // Clear unread count locally
    94→      setConversations((prev) =>
    95→        prev.map((c) => (c.id === activeId ? { ...c, unreadCount: 0 } : c))
    96→      );
    97→    });
    98→  }, [activeId, userId]);
    99→
   100→  // Scroll to bottom when messages change
   101→  useEffect(() => {
   102→    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
   103→  }, [messages]);
   104→
   105→  // Real-time subscription
   106→  useEffect(() => {
   107→    if (!activeId) return;
   108→    const supabase = createClient();
   109→    const channel = supabase
   110→      .channel(`messages:${activeId}`)
   111→      .on(
   112→        "postgres_changes",
   113→        {
   114→          event: "INSERT",
   115→          schema: "messaging",
   116→          table: "messages",
   117→          filter: `conversation_id=eq.${activeId}`,
   118→        },
   119→        (payload) => {
   120→          const newMsg = payload.new as MessageRow;
   121→          setMessages((prev) => {
   122→            // Avoid duplicate if we already optimistically added it
   123→            if (prev.find((m) => m.id === newMsg.id)) return prev;
   124→            return [...prev, newMsg];
   125→          });
   126→          // Update last message in sidebar
   127→          setConversations((prev) =>
   128→            prev.map((c) =>
   129→              c.id === activeId
   130→                ? {
   131→                    ...c,
   132→                    lastMessage: {
   133→                      body: newMsg.body,
   134→                      created_at: newMsg.created_at,
   135→                      sender_id: newMsg.sender_id,
   136→                    },
   137→                    updated_at: newMsg.created_at,
   138→                  }
   139→                : c
   140→            )
   141→          );
   142→          // Mark read immediately if it's from the other person
   143→          if (newMsg.sender_id !== userId) {
   144→            markMessagesRead(activeId, userId);
   145→          }
   146→        }
   147→      )
   148→      .subscribe();
   149→
   150→    return () => {
   151→      supabase.removeChannel(channel);
   152→    };
   153→  }, [activeId, userId]);
   154→
   155→  // Debounced user search
   156→  const handleRecipientSearch = useCallback((query: string) => {
   157→    setRecipientSearch(query);
   158→    if (searchDebounceRef.current) clearTimeout(searchDebounceRef.current);
   159→    if (!query.trim()) {
   160→      setRecipientResults([]);
   161→      return;
   162→    }
   163→    searchDebounceRef.current = setTimeout(async () => {
   164→      setSearchingUsers(true);
   165→      const results = await searchUsers(query);
   166→      setRecipientResults(results);
   167→      setSearchingUsers(false);
   168→    }, 300);
   169→  }, []);
   170→
   171→  const handleSelectRecipient = async (recipient: { id: string; full_name: string }) => {
   172→    setCreatingConvo(true);
   173→    const convoId = await createConversation(userId, recipient.id);
   174→    if (convoId) {
   175→      // Refresh conversations
   176→      const updated = await getConversations(userId);
   177→      setConversations(updated);
   178→      setActiveId(convoId);
   179→      setMobileShowChat(true);
   180→    }
   181→    setShowNewModal(false);
   182→    setRecipientSearch("");
   183→    setRecipientResults([]);
   184→    setCreatingConvo(false);
   185→  };
   186→
   187→  const handleSend = async () => {
   188→    if (!draft.trim() || !activeId || sending) return;
   189→    const body = draft.trim();
   190→    setDraft("");
   191→    setSending(true);
   192→
   193→    // Optimistic message
   194→    const tempId = `temp-${Date.now()}`;
   195→    const optimistic: MessageRow = {
   196→      id: tempId,
   197→      conversation_id: activeId,
   198→      sender_id: userId,
   199→      body,
   200→      created_at: new Date().toISOString(),
   201→      read_at: null,
   202→    };
   203→    setMessages((prev) => [...prev, optimistic]);
   204→
   205→    const saved = await sendMessage(activeId, body);
   206→
   207→    // Replace optimistic with real row
   208→    if (saved) {
   209→      setMessages((prev) => prev.map((m) => (m.id === tempId ? saved : m)));
   210→      setConversations((prev) =>
   211→        prev.map((c) =>
   212→          c.id === activeId
   213→            ? {
   214→                ...c,
   215→                lastMessage: { body: saved.body, created_at: saved.created_at, sender_id: saved.sender_id },
   216→                updated_at: saved.created_at,
   217→              }
   218→            : c
   219→        )
   220→      );
   221→    } else {
   222→      // Remove optimistic on failure
   223→      setMessages((prev) => prev.filter((m) => m.id !== tempId));
   224→    }
   225→    setSending(false);
   226→  };
   227→
   228→  const filtered = conversations.filter(
   229→    (c) =>
   230→      c.otherUser.full_name.toLowerCase().includes(search.toLowerCase())
   231→  );
   232→
   233→  return (
   234→    <div className="flex flex-1 bg-white overflow-hidden">
   235→      {/* Conversation list */}
   236→      <div className={`w-full md:w-80 md:min-w-[320px] border-r border-gray-100 flex flex-col ${mobileShowChat ? "hidden md:flex" : "flex"}`}>
   237→        {/* Search + New Message */}
   238→        <div className="p-3 border-b border-gray-100">
   239→          <div className="relative mb-2">
   240→            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
   241→            <input
   242→              type="text"
   243→              placeholder="Search conversations..."
   244→              value={search}
   245→              onChange={(e) => setSearch(e.target.value)}
   246→              className="w-full pl-9 pr-3 py-2 text-sm font-body bg-gray-50 border border-gray-100 rounded-lg focus:outline-none focus:ring-2 focus:ring-[#4a7c59]/20 focus:border-[#4a7c59]/40"
   247→            />
   248→          </div>
   249→          <button
   250→            onClick={() => setShowNewModal(true)}
   251→            className="w-full flex items-center justify-center gap-2 bg-[#4a7c59] hover:bg-[#3d6849] text-white text-sm font-medium py-2 rounded-lg transition-colors cursor-pointer"
   252→          >
   253→            <SquarePen className="w-4 h-4" />
   254→            New Message
   255→          </button>
   256→        </div>
   257→
   258→        {/* List */}
   259→        <div className="flex-1 overflow-y-auto">
   260→          {loadingConvos ? (
   261→            <div className="flex items-center justify-center py-10">
   262→              <Loader2 className="w-5 h-5 animate-spin text-gray-300" />
   263→            </div>
   264→          ) : filtered.length === 0 ? (
   265→            <p className="text-sm text-gray-400 font-body text-center py-8">
   266→              {search ? "No conversations found" : "No messages yet. Start one!"}
   267→            </p>
   268→          ) : (
   269→            filtered.map((convo) => (
   270→              <button
   271→                key={convo.id}
   272→                onClick={() => {
   273→                  setActiveId(convo.id);
   274→                  setMobileShowChat(true);
   275→                }}
   276→                className={`w-full flex items-start gap-3 px-4 py-3.5 text-left transition-colors cursor-pointer ${
   277→                  convo.id === activeId
   278→                    ? "bg-[#4a7c59]/5 border-r-2 border-[#4a7c59]"
   279→                    : "hover:bg-gray-50"
   280→                }`}
   281→              >
   282→                <div className={`${colorForId(convo.otherUser.id)} w-10 h-10 rounded-full flex items-center justify-center text-white text-xs font-semibold font-body shrink-0`}>
   283→                  {initialsFor(convo.otherUser.full_name)}
   284→                </div>
   285→                <div className="flex-1 min-w-0">
   286→                  <div className="flex items-center justify-between">
   287→                    <span className="text-sm font-semibold font-body text-gray-800 truncate">
   288→                      {convo.otherUser.full_name}
   289→                    </span>
   290→                    {convo.lastMessage && (
   291→                      <span className="text-[11px] text-gray-400 font-body shrink-0 ml-2">
   292→                        {formatTime(convo.lastMessage.created_at)}
   293→                      </span>
   294→                    )}
   295→                  </div>
   296→                  <div className="flex items-center gap-2 mt-0.5">
   297→                    <p className="text-xs text-gray-500 font-body truncate flex-1">
   298→                      {convo.lastMessage?.body ?? "No messages yet"}
   299→                    </p>
   300→                    {convo.unreadCount > 0 && (
   301→                      <span className="bg-[#4a7c59] text-white text-[10px] font-bold w-5 h-5 rounded-full flex items-center justify-center shrink-0">
   302→                        {convo.unreadCount}
   303→                      </span>
   304→                    )}
   305→                  </div>
   306→                </div>
   307→              </button>
   308→            ))
   309→          )}
   310→        </div>
   311→      </div>
   312→
   313→      {/* Chat area */}
   314→      <div className={`flex-1 flex flex-col ${mobileShowChat ? "flex" : "hidden md:flex"}`}>
   315→        {!active ? (
   316→          <div className="flex-1 flex items-center justify-center">
