    22→function colorForId(id: string): string {
    23→  const palette = ["#4a7c59", "#7c6b4a", "#5a6b8a", "#8a5a6b", "#6b7c4a", "#4a6b7c"];
    24→  let hash = 0;
    25→  for (let i = 0; i < id.length; i++) hash = id.charCodeAt(i) + ((hash << 5) - hash);
    26→  return palette[Math.abs(hash) % palette.length];
    27→}
    28→
    29→function initialsFor(name: string): string {
    30→  return name
    31→    .split(" ")
    32→    .filter(Boolean)
    33→    .slice(0, 2)
    34→    .map((w) => w[0].toUpperCase())
    35→    .join("");
    36→}
    37→
    38→function formatTime(iso: string): string {
    39→  const date = new Date(iso);
    40→  const now = new Date();
    41→  const diffDays = Math.floor((now.getTime() - date.getTime()) / 86400000);
    42→  if (diffDays === 0) return date.toLocaleTimeString([], { hour: "numeric", minute: "2-digit" });
    43→  if (diffDays === 1) return "Yesterday";
    44→  if (diffDays < 7) return date.toLocaleDateString([], { weekday: "short" });
    45→  return date.toLocaleDateString([], { month: "short", day: "numeric" });
    46→}
