    48→    .schema("messaging")
    49→    .from("conversations")
    50→    .select("id, updated_at")
    51→    .in("id", conversationIds)
    52→    .order("updated_at", { ascending: false });
    53→
    54→  if (cErr) console.error("[getConversations] convos error:", cErr);
    55→  if (cErr || !convos?.length) return [];
