    59→    .schema("messaging")
    60→    .from("conversation_participants")
    61→    .select("conversation_id, user_id")
    62→    .in("conversation_id", conversationIds);
    63→
    64→  // Get the other user ids (not current user)
    65→  const otherUserIds = [
    66→    ...new Set(
    67→      (allParticipants ?? [])
    68→        .filter((p) => p.user_id !== userId)
    69→        .map((p) => p.user_id)
    70→    ),
    71→  ];
